#!/usr/bin/env bash
# Inject an `assemble-install` target into immortalwrt/package/Makefile.
#
# Why: the normal rootfs creation step is the recipe of `$(curdir)/install`
# (== `package/install`).  Calling `make package/install` from a cross-job
# assemble step is not possible, because that same target name is also the
# aggregate over every package's `package/<pkg>/install` prereq (generated by
# include/subdir.mk), and those per-package install targets would recompile all
# packages whose build_dir is not present in the assemble runner.
#
# So we extract the *recipe* of `$(curdir)/install` verbatim (including its own
# deps: package/merge + package/merge-index) and re-emit it under a new target
# name that has no aggregate prerequisites.  The extracted text is copied
# mechanically from the checked out tree - no hand-written recipe.
set -euo pipefail

TREE="${1:-immortalwrt}"
cd "$TREE"

if grep -q '^assemble-install:' package/Makefile; then
  echo "assemble-install already injected"
  exit 0
fi

FRAG=$(mktemp)
awk '
  /^\$\(curdir\)\/install:/ { inrule=1; sub(/^\$\(curdir\)\/install:/, "assemble-install:"); print; next }
  inrule && /^\$\(/ { inrule=0 }
  inrule { print }
' package/Makefile > "$FRAG"

if ! grep -q '^assemble-install:' "$FRAG"; then
  echo "ERROR: could not find the '$(curdir)/install:' rule in package/Makefile"
  grep -n 'curdir)/install' package/Makefile || true
  rm -f "$FRAG"
  exit 1
fi

if ! grep -q 'apk_install_list\|opkg_install_list' "$FRAG"; then
  echo "ERROR: extracted assemble-install recipe does not contain an install command"
  cat "$FRAG"
  rm -f "$FRAG"
  exit 1
fi

cat "$FRAG" >> package/Makefile
rm -f "$FRAG"
echo "=== injected assemble-install target ($(wc -l < package/Makefile) lines now in package/Makefile) ==="
sed -n '/^assemble-install:/,$p' package/Makefile | head -n 45
